### COMBAT MODE (Multiple Hostiles - Time Limited)
```javascript
// ✅ CORRECT - Sustained combat mode with timeout
const combatDurationMs = 60000;  // 60 seconds
const combatRadius = 20;
const hostileTypes = ['zombie', 'skeleton', 'creeper', 'spider', 'drowned', 'husk'];
const startTime = Date.now();

while (Date.now() - startTime < combatDurationMs && bot.health >= 10) {
    let target = Object.values(bot.entities)
        .filter(e => hostileTypes.includes(e.name))
        .filter(e => e.position.distanceTo(bot.entity.position) < combatRadius)
        .sort((a, b) => 
            a.position.distanceTo(bot.entity.position) - 
            b.position.distanceTo(bot.entity.position)
        )[0];

    if (target) {
        const distance = target.position.distanceTo(bot.entity.position);
        if (distance <= 3.5) {
            await bot.lookAt(target.position);
            await bot.attack(target);
        } else {
            await bot.lookAt(target.position);
            bot.setControlState('forward', true);
            await skills.wait(bot, 300);
            bot.setControlState('forward', false);
        }
    }
    await skills.wait(bot, 250);
}
console.log('[SoldierX] Combat mode ended - time expired');
```

