## COMPLETE COMBAT TEMPLATE (MANDATORY)

Every soldier MUST use this exact template structure:
```javascript
// === SOLDIER COMBAT TEMPLATE ===
const SOLDIER_NAME = 'SoldierX';
const TARGET_TYPE = 'iron_golem'; // For mobs/animals use lowercase name
const SEARCH_RANGE = 30;
const MELEE_RANGE = 3.5;
const RETREAT_HEALTH = 12;
const MAX_COMBAT_TIME = 60000; // 60 seconds

console.log('[' + SOLDIER_NAME + '] === COMBAT START ===');
console.log('[' + SOLDIER_NAME + '] Position:', bot.entity.position);
console.log('[' + SOLDIER_NAME + '] Health:', bot.health);

// STEP 1: Equip weapon
const weapon = bot.inventory.items().find(i => i.name.includes('sword')) || 
               bot.inventory.items().find(i => i.name.includes('axe')) || null;
console.log('[' + SOLDIER_NAME + '] Weapon:', weapon ? weapon.name : 'NONE (fists - low damage!)');
if (weapon) await bot.equip(weapon, 'hand');

// STEP 2: Find target
let target = Object.values(bot.entities).find(e => 
    e.name === TARGET_TYPE && 
    e.position.distanceTo(bot.entity.position) < SEARCH_RANGE
);
console.log('[' + SOLDIER_NAME + '] Target ' + TARGET_TYPE + ':', 
    target ? 'FOUND at ' + Math.floor(target.position.distanceTo(bot.entity.position)) + ' blocks' : 'NOT FOUND');

if (!target) {
    console.log('[' + SOLDIER_NAME + '] ERROR: No target found, ending task');
} else {
    // STEP 3: Combat loop with timeout
    const startTime = Date.now();
    let hits = 0;

    console.log('[' + SOLDIER_NAME + '] Engaging target...');

    while (target && target.isValid) {
        // TIMEOUT CHECK
        if (Date.now() - startTime > MAX_COMBAT_TIME) {
            console.log('[' + SOLDIER_NAME + '] TIMEOUT - combat exceeded ' + (MAX_COMBAT_TIME/1000) + 's');
            break;
        }

        // HEALTH CHECK
        if (bot.health < RETREAT_HEALTH) {
            console.log('[' + SOLDIER_NAME + '] LOW HEALTH (' + bot.health + '), RETREATING!');
            bot.setControlState('back', true);
            await skills.wait(bot, 1500);
            bot.setControlState('back', false);
            break;
        }

        const distance = target.position.distanceTo(bot.entity.position);

        // RANGE CHECK
        if (distance > SEARCH_RANGE) {
            console.log('[' + SOLDIER_NAME + '] Target out of range (' + Math.floor(distance) + 'm), stopping');
            break;
        }

        await bot.lookAt(target.position);

        if (distance <= MELEE_RANGE) {
            // IN RANGE - ATTACK
            await bot.attack(target);
            hits++;
            if (hits % 5 === 0) {
                console.log('[' + SOLDIER_NAME + '] Hits: ' + hits + ' | Health: ' + bot.health + ' | Dist: ' + Math.floor(distance) + 'm');
            }
        } else {
            // CLOSE DISTANCE
            bot.setControlState('forward', true);
            bot.setControlState('sprint', true);
            await skills.wait(bot, 300);
            bot.setControlState('forward', false);
            bot.setControlState('sprint', false);
        }

        await skills.wait(bot, 350);
        target = bot.entities[target.id]; // Refresh target
    }

    console.log('[' + SOLDIER_NAME + '] Combat complete. Total hits: ' + hits + ', Final health: ' + bot.health);
}

console.log('[' + SOLDIER_NAME + '] === TASK COMPLETE ===');
```

